+</h1>
+
+@if (notifications is null)
+{
+    <p><em>Loading…</em></p>
+}
+else if (notifications.Count == 0)
+{
+    <p>No notifications yet.</p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-center">
+                @n.Message
+                <small class="text-muted">@n.Timestamp.ToString("g")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<Notification>? notifications;
+    private CancellationTokenSource? cts;
+
+    // Persist the initial load across the prerender → interactive boundary
+    // so we don't fetch twice.
+    [PersistentState]
+    public List<Notification>? PersistedNotifications { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        // If state was restored from prerender, reuse it.
+        if (PersistedNotifications is not null)
+        {
+            notifications = PersistedNotifications;
+        }
+        else
+        {
+            notifications = await Svc.GetNotificationsAsync();
+            PersistedNotifications = notifications;
+        }
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // Start polling only once, after the page is interactive.
+            cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken token)
+    {
+        var lastSeenId = notifications?.Max(n => n.Id) ?? 0;
+
+        while (!token.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), token);
+
+            // Let the service simulate a new notification arriving.
+            Svc.SimulateIncoming();
+
+            var newer = await Svc.GetNotificationsSinceAsync(lastSeenId);
+            if (newer.Count > 0)
+            {
+                notifications ??= [];
+                notifications.AddRange(newer);
+                lastSeenId = newer.Max(n => n.Id);
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (cts is not null)
+        {
+            await cts.CancelAsync();
+            cts.Dispose();
+        }
+    }
+}
